begin;
create temporary table chat_fixture(owner_id uuid,speaker_id uuid,outsider_id uuid,community_id uuid,channel_id uuid,other_channel uuid,legacy_id uuid,shared_id uuid)on commit drop;
insert into chat_fixture select gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid();grant select on chat_fixture to authenticated;
insert into auth.users(id,aud,role,email,raw_user_meta_data,raw_app_meta_data,created_at,updated_at)select u,'authenticated','authenticated','qa-'||u||'@example.invalid',jsonb_build_object('display_name','QA_'||substr(replace(u::text,'-',''),1,16)),'{}'::jsonb,now(),now()from chat_fixture cross join lateral unnest(array[owner_id,speaker_id,outsider_id])u;
insert into public.communities(id,name,created_by,invite_only)select community_id,'QA voice chat',owner_id,true from chat_fixture;
insert into public.community_members(community_id,user_id)select community_id,speaker_id from chat_fixture;
insert into public.channels(id,community_id,name,kind,created_by)select u,community_id,'QA '||substr(u::text,1,8),'voice',owner_id from chat_fixture cross join lateral unnest(array[channel_id,other_channel])u;
set local role authenticated;
do $$declare f record;denied boolean;begin select * into f from chat_fixture;perform set_config('request.jwt.claim.sub',f.speaker_id::text,true);
 insert into public.voice_chat_messages(channel_id,author_id,content)values(f.channel_id,f.speaker_id,'Room text');
 denied:=false;begin insert into public.voice_chat_messages(channel_id,author_id,content,kind,transcript_id)values(f.channel_id,f.speaker_id,'Forged transcript','transcript',f.legacy_id);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Forged transcript allowed';end if;
 denied:=false;begin insert into public.voice_chat_messages(channel_id,author_id,content)values(f.channel_id,f.owner_id,'Forged author');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Forged author allowed';end if;
 perform set_config('request.jwt.claim.sub',f.outsider_id::text,true);
 if exists(select 1 from public.voice_chat_messages where channel_id=f.channel_id)then raise exception'Outsider read private call chat';end if;
 denied:=false;begin insert into public.voice_chat_messages(channel_id,author_id,content)values(f.channel_id,f.outsider_id,'Forbidden room');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception'Outsider wrote in call chat';end if;
 perform set_config('request.jwt.claim.sub',f.owner_id::text,true);
 if(select count(*)from public.voice_chat_messages where channel_id=f.channel_id)<>1 then raise exception'Room owner cannot read chat';end if;
end $$;
reset role;
delete from public.call_transcripts where id=(select shared_id from chat_fixture);
do $$begin if exists(select 1 from public.voice_chat_messages where transcript_id=(select shared_id from chat_fixture))then raise exception'Deleted transcript still in room chat';end if;end $$;
rollback;
